import{_ as t,o as d,c as a,a2 as s}from"./chunks/framework.CZqXuAiL.js";const u=JSON.parse('{"title":"API Reference","description":"Firewall-Plus REST APIs — the node daemon API (port 8472) and the Pterodactyl client API (/v1/firewall).","frontmatter":{"title":"API Reference","description":"Firewall-Plus REST APIs — the node daemon API (port 8472) and the Pterodactyl client API (/v1/firewall)."},"headers":[],"relativePath":"firewall-plus/fwp-aside/user-guide/api.md","filePath":"firewall-plus/fwp-aside/user-guide/api.md","lastUpdated":1785959583000}'),i={name:"firewall-plus/fwp-aside/user-guide/api.md"};function r(o,e,l,c,n,h){return d(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="api-reference" tabindex="-1">API Reference <a class="header-anchor" href="#api-reference" aria-label="Permalink to &quot;API Reference&quot;">​</a></h1><p>Two REST surfaces:</p><ul><li><strong>Node API</strong> — the <code>firewall-plus</code> daemon on each Wings host (default <code>http://127.0.0.1:8472/api/v1</code>), called by the panel and by operators.</li><li><strong>Client API</strong> — panel-side endpoints under the Pterodactyl client API, used by the server firewall UI and any integrations.</li></ul><hr><h2 id="node-api" tabindex="-1">Node API <a class="header-anchor" href="#node-api" aria-label="Permalink to &quot;Node API&quot;">​</a></h2><p>Base URL: <code>http://&lt;node&gt;:8472/api/v1</code> · Auth: <code>Authorization: Bearer &lt;64-hex token&gt;</code> (from <code>/etc/firewall-plus/token</code>) plus the <code>allowedIps</code> IP whitelist. Exceeding a rate limit returns <code>429</code> with <code>Retry-After</code>.</p><table tabindex="0"><thead><tr><th>Route</th><th>Rate limit (per source IP)</th></tr></thead><tbody><tr><td><code>POST /firewall/apply</code></td><td>10/min</td></tr><tr><td><code>POST /firewall/flush*</code>, <code>DELETE /smart/mitigation/*</code></td><td>5/min</td></tr><tr><td><code>GET /health</code></td><td>60/min</td></tr><tr><td>Other protected routes</td><td>30/min</td></tr></tbody></table><h3 id="health" tabindex="-1">Health <a class="header-anchor" href="#health" aria-label="Permalink to &quot;Health&quot;">​</a></h3><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/v1/health</span></span></code></pre></div><p>Reports daemon version and capabilities — the panel uses this for the ONLINE/OFFLINE badge and version display:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;success&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;data&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;input_jump_style&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;per-port-dport-v2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;geoip_available&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;meta&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1.0.4&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h3 id="firewall-apply-lifecycle" tabindex="-1">Firewall apply &amp; lifecycle <a class="header-anchor" href="#firewall-apply-lifecycle" aria-label="Permalink to &quot;Firewall apply &amp; lifecycle&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Description</th></tr></thead><tbody><tr><td><code>POST</code></td><td><code>/api/v1/firewall/apply</code></td><td>Queue an atomic apply for a server (rules + ipsets + optional <code>smart</code> block). Processed serially by the queue worker with snapshot + rollback.</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/firewall/queue</code></td><td>Inspect the apply queue (pending/processing entries).</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/firewall/status/:serverId</code></td><td>Last apply status for a server (the panel polls this).</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/firewall/sync</code></td><td>Push full desired state for reconciliation.</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/firewall/sync</code></td><td>Inspect the node&#39;s current view of synced state.</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/firewall/verify</code></td><td>Run drift verification — compares live iptables/ipset state against the stored desired config and reports differences.</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/firewall/flush/:serverId</code></td><td>Remove all <code>FWP-*</code> chains and <code>fwp-*</code> ipsets for one server.</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/firewall/flush-rule-types/:serverId</code></td><td>Flush only specific rule types for a server (used by emergency per-type disables).</td></tr></tbody></table><p>Apply payloads carry an <code>X-Correlation-ID</code> that shows up in node logs and panel audit entries — trace a single apply panel → queue → node with it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> firewall-plus</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;&lt;correlation-uuid&gt;&#39;</span></span></code></pre></div><h3 id="smart-endpoints" tabindex="-1">SMART endpoints <a class="header-anchor" href="#smart-endpoints" aria-label="Permalink to &quot;SMART endpoints&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Description</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/v1/smart/status/:serverId</code></td><td>Monitor state for a server (baseline, current level, active mitigation).</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/smart/events</code></td><td>Recent attack events from the node log (the panel syncs these every 2 minutes).</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/smart/events/ack</code></td><td>Acknowledge events by id.</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/smart/event</code></td><td>Record an externally-detected event (used by integrations/testing).</td></tr><tr><td><code>DELETE</code></td><td><code>/api/v1/smart/mitigation/:serverId</code></td><td>Manually clear the active mitigation for a server.</td></tr></tbody></table><h3 id="metrics-endpoints" tabindex="-1">Metrics endpoints <a class="header-anchor" href="#metrics-endpoints" aria-label="Permalink to &quot;Metrics endpoints&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Description</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/v1/metrics/:serverId/summary</code></td><td>Aggregate counters (packets/bytes dropped, passed) for a server. 60/min.</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/metrics/:serverId/timeseries</code></td><td>Time-bucketed series for charts. 30/min.</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/metrics/:serverId/rules</code></td><td>Per-rule hit counters. 30/min.</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/metrics/:serverId/sources</code></td><td>Top source IPs. 30/min.</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/metrics/batch</code></td><td>Batch metric ingest. 20/min.</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/metrics/:serverId/reset</code></td><td>Reset one server&#39;s counters. 10/min.</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/metrics/node/reset-all</code></td><td>Reset all counters on the node. 5/min.</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/metrics/node/summary</code></td><td>Node-wide aggregate. 30/min.</td></tr></tbody></table><hr><h2 id="client-api-panel" tabindex="-1">Client API (panel) <a class="header-anchor" href="#client-api-panel" aria-label="Permalink to &quot;Client API (panel)&quot;">​</a></h2><p>Base URL: <code>/api/client/servers/{server}/v1/firewall</code> — authenticated with a normal Pterodactyl <strong>client API key</strong>, subject to subuser permissions (<code>firewall.read</code>, <code>firewall.manage</code>, <code>firewall.abusedb</code>).</p><div class="warning custom-block"><p class="custom-block-title">Use the <code>/v1/</code> prefix</p><p>The canonical namespace is <code>/api/client/servers/{server}/v1/firewall/...</code>. The unprefixed <code>/firewall/...</code> routes are a <strong>deprecated</strong> back-compat alias that emits RFC 8594 headers (<code>Deprecation: true</code>, <code>Sunset: Fri, 01 Jan 2027 00:00:00 GMT</code>, and a <code>Link: ...; rel=&quot;successor-version&quot;</code>). New code must use <code>/v1/</code>.</p></div><p><strong>Response envelope</strong> on every endpoint:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;success&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;data&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { }, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;error&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">null</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;meta&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { } }</span></span></code></pre></div><p>Every response includes an <code>X-Correlation-ID</code> header — include it in bug reports; it&#39;s stored in the audit log and forwarded to the node on applies.</p><h3 id="rate-limits-per-user-server" tabindex="-1">Rate limits (per user + server) <a class="header-anchor" href="#rate-limits-per-user-server" aria-label="Permalink to &quot;Rate limits (per user + server)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Bucket</th><th>Limit</th><th>Covers</th></tr></thead><tbody><tr><td><code>firewall-apply</code></td><td>3/min</td><td><code>POST .../firewall/apply</code></td></tr><tr><td><code>firewall-mutations</code></td><td>20/min</td><td>Rule/preset/SMART mutations, event ack</td></tr><tr><td><code>firewall-lists</code></td><td>30/min</td><td>Whitelist/blacklist add &amp; delete</td></tr><tr><td><code>firewall-list-uploads</code></td><td>throttled separately</td><td>Bulk list imports</td></tr></tbody></table><h3 id="read-endpoints-firewall-read" tabindex="-1">Read endpoints (<code>firewall.read</code>) <a class="header-anchor" href="#read-endpoints-firewall-read" aria-label="Permalink to &quot;Read endpoints (`firewall.read`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Description</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/firewall</code></td><td>Dashboard payload (state, counts, sync status).</td></tr><tr><td><code>GET</code></td><td><code>/firewall/apply/status</code></td><td>Poll the in-flight apply.</td></tr><tr><td><code>GET</code></td><td><code>/firewall/stats</code></td><td>Traffic/drop stats.</td></tr><tr><td><code>GET</code></td><td><code>/firewall/logs</code></td><td>Activity + SMART event log for the server.</td></tr><tr><td><code>GET</code></td><td><code>/firewall/smart</code></td><td>SMART config and status.</td></tr><tr><td><code>GET</code></td><td><code>/firewall/rules</code></td><td>List rules.</td></tr><tr><td><code>GET</code></td><td><code>/firewall/whitelist</code> · <code>/firewall/blacklist</code></td><td>List entries.</td></tr><tr><td><code>GET</code></td><td><code>/firewall/presets</code></td><td>System + user presets.</td></tr><tr><td><code>GET</code></td><td><code>/firewall/metrics/summary</code> · <code>/timeseries</code> · <code>/rules</code> · <code>/sources</code></td><td>Chart data for the dashboard.</td></tr></tbody></table><h3 id="mutations-firewall-manage-tos-accepted" tabindex="-1">Mutations (<code>firewall.manage</code> + ToS accepted) <a class="header-anchor" href="#mutations-firewall-manage-tos-accepted" aria-label="Permalink to &quot;Mutations (`firewall.manage` + ToS accepted)&quot;">​</a></h3><p>Mutations additionally pass through <code>firewall.tos</code> (Terms must be accepted), <code>firewall.emergency</code> (blocked while emergency mode is on), and <code>firewall.owner_addon</code> checks.</p><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Description</th></tr></thead><tbody><tr><td><code>POST</code></td><td><code>/firewall/tos/accept</code></td><td>Accept the Terms of Service.</td></tr><tr><td><code>PUT</code></td><td><code>/firewall/enabled</code></td><td>Toggle Firewall-Plus for this server (<code>addon_enabled</code>). Off = node flush job.</td></tr><tr><td><code>POST</code></td><td><code>/firewall/rules</code></td><td>Create a rule.</td></tr><tr><td><code>PUT</code></td><td><code>/firewall/rules/{id}</code></td><td>Update a rule.</td></tr><tr><td><code>PATCH</code></td><td><code>/firewall/rules/{id}/enabled</code></td><td>Enable/disable a rule without deleting it.</td></tr><tr><td><code>DELETE</code></td><td><code>/firewall/rules/{id}</code></td><td>Delete a rule.</td></tr><tr><td><code>POST</code></td><td><code>/firewall/apply</code></td><td>Queue an apply to the node (<code>firewall-apply</code> throttle, 3/min).</td></tr><tr><td><code>PUT</code></td><td><code>/firewall/smart</code></td><td>Update SMART settings (requires admin SMART grant).</td></tr><tr><td><code>PUT</code></td><td><code>/firewall/smart/webhook</code></td><td>Set the per-server owner Discord webhook.</td></tr><tr><td><code>POST</code></td><td><code>/firewall/smart/events/{id}/ack</code></td><td>Acknowledge a SMART event.</td></tr><tr><td><code>POST</code></td><td><code>/firewall/whitelist</code> · <code>/blacklist</code></td><td>Add an entry.</td></tr><tr><td><code>POST</code></td><td><code>/firewall/whitelist/bulk</code> · <code>/blacklist/bulk</code></td><td>Bulk import (paste/upload many entries).</td></tr><tr><td><code>DELETE</code></td><td><code>/firewall/whitelist/{id}</code> · <code>/blacklist/{id}</code></td><td>Remove an entry.</td></tr><tr><td><code>POST</code></td><td><code>/firewall/presets</code></td><td>Save a user preset.</td></tr><tr><td><code>POST</code></td><td><code>/firewall/presets/{preset}/apply</code></td><td>Instantiate a preset&#39;s rules.</td></tr><tr><td><code>DELETE</code></td><td><code>/firewall/presets/{preset}</code></td><td>Delete a user preset.</td></tr><tr><td><code>POST</code></td><td><code>/firewall/metrics/reset</code></td><td>Reset the server&#39;s metric counters.</td></tr></tbody></table><h3 id="abuseipdb-endpoints-firewall-abusedb" tabindex="-1">AbuseIPDB endpoints (<code>firewall.abusedb</code>) <a class="header-anchor" href="#abuseipdb-endpoints-firewall-abusedb" aria-label="Permalink to &quot;AbuseIPDB endpoints (`firewall.abusedb`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Description</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/firewall/abusedb/status</code></td><td>Whether a key is configured and the feature is enabled.</td></tr><tr><td><code>POST</code></td><td><code>/firewall/abusedb/verify-key</code></td><td>Validate &amp; store the user&#39;s AbuseIPDB API key.</td></tr><tr><td><code>DELETE</code></td><td><code>/firewall/abusedb/key</code></td><td>Remove the stored key.</td></tr><tr><td><code>POST</code></td><td><code>/firewall/abusedb/check</code></td><td>Run a lookup against an IP.</td></tr><tr><td><code>POST</code></td><td><code>/firewall/abusedb/saved</code></td><td>Save a lookup.</td></tr><tr><td><code>GET</code></td><td><code>/firewall/abusedb/saved</code> · <code>/saved/{id}</code></td><td>List / show saved lookups.</td></tr><tr><td><code>DELETE</code></td><td><code>/firewall/abusedb/saved/{id}</code></td><td>Delete a saved lookup.</td></tr></tbody></table><p>Grant subusers access in the server&#39;s <strong>Users</strong> tab: <strong>Firewall → Read / Manage / AbuseDB Access</strong>. Manage implies read.</p>',36)])])}const k=t(i,[["render",r]]);export{u as __pageData,k as default};
